// YouTube channel RSS feeds - ADD YOUR CHANNELS HERE
const channels = [
  { name: 'Fireship', id: 'UCsBjURrPoezykLs9EqgamOA' },
  { name: 'Theo', id: 'UCbRP3c757lWg9M-U7TyEkXA' },
  { name: 'ThePrimeagen', id: 'UCUyeluBRhGPCW4rPe_UvBZQ' },
];

return channels.map(ch => ({
  json: {
    channel_name: ch.name,
    feed_url: `https://www.youtube.com/feeds/videos.xml?channel_id=${ch.id}`
  }
}));

// Parse RSS XML and extract video entries
const xml = $input.first().json.data;
const entries = [];
const regex = /<entry>(.*?)<\/entry>/gs;
let match;
while ((match = regex.exec(xml)) !== null) {
  const entry = match[1];
  const title = entry.match(/<title>(.*?)<\/title>/)?.[1] || '';
  const videoId = entry.match(/<yt:videoId>(.*?)<\/yt:videoId>/)?.[1] || '';
  const published = entry.match(/<published>(.*?)<\/published>/)?.[1] || '';
  const description = entry.match(/<media:description>(.*?)<\/media:description>/s)?.[1] || '';
  entries.push({ json: { title, videoId, published, description, url: `https://youtube.com/watch?v=${videoId}` } });
}
return entries.slice(0, 10); // Last 10 videos

