// Format all summaries into HTML email
const items = $input.all();
let html = '<h2>Weekly YouTube Digest</h2>';
html += `<p style="color:#666">${new Date().toLocaleDateString()} - ${items.length} videos</p>`;

for (const item of items) {
  const summary = item.json?.candidates?.[0]?.content?.parts?.[0]?.text || 'Summary unavailable';
  html += `<div style="margin:16px 0;padding:12px;border-left:3px solid #4285f4">`;
  html += `<strong><a href="${item.json.url}">${item.json.title}</a></strong>`;
  html += `<p style="color:#333;margin:8px 0">${summary}</p>`;
  html += `</div>`;
}

return [{ json: { subject: `YouTube Digest - ${new Date().toLocaleDateString()}`, html } }];
